def test_remix_moving_pool_respects_lookahead_visits_skips_and_manual_ranges(tmp_path):
    fixtures={'com/aidj/music/RemixProbe.java':r'''package com.aidj.music;
import org.json.*;import java.util.*;
public class RemixProbe {
 static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 static JSONObject cue(double start,double bpm){return new JSONObject().put("start",start).put("end",start+12).put("bpm",bpm).put("fade",.7).put("mix",2).put("entryVerified",true);}
 static JSONObject queue(){JSONObject q=new JSONObject().put("djEnabled",true).put("djRemix",true).put("currentId","e0");JSONArray entries=new JSONArray();JSONObject tracks=new JSONObject();for(int i=0;i<14;i++){String id="t"+i;tracks.put(id,new JSONObject().put("duration",240).put("id",id));JSONArray cs=new JSONArray();for(int k=0;k<3;k++)cs.put(cue(40+30*k,i==0||i==2||i==13?128:160).put("energy",1-k*.4));entries.put(new JSONObject().put("id","e"+i).put("trackId",id).put("remixCues",cs));}return q.put("tracks",tracks).put("entries",entries);}
 public static void main(String[] ignored){
 JSONObject q=queue();RemixPlan.arrange(q);JSONArray entries=q.getJSONArray("entries");check(entries.length()==14&&entries.getJSONObject(1).getString("id").equals("e2"),"tempo fit can select a near neighbour but never a distant ideal match");
 check(entries.getJSONObject(0).getJSONObject("dj").getDouble("start")==40,"first validated snippet selected");
 Map<String,Integer> counts=new HashMap<>();int steps=0;boolean revisited=false;
 while(q.getJSONArray("entries").length()>0&&steps<100){entries=q.getJSONArray("entries");Set<String> ids=new HashSet<>();for(int i=0;i<entries.length();i++)check(ids.add(entries.getJSONObject(i).getString("id")),"pool never duplicates queue entries");JSONObject e=entries.getJSONObject(0);String id=e.getString("id");int visit=counts.getOrDefault(id,0);check(e.getJSONObject("dj").getDouble("start")==40+visit*30,"returns choose a different validated section");counts.put(id,visit+1);if(visit>0)revisited=true;RemixPlan.finish(q,id,"",false);steps++;}
 check(steps==42&&revisited&&q.getJSONArray("entries").length()==0,"all entries leave after exactly three distinct visits");for(int count:counts.values())check(count==3,"visit limit holds");
 q=queue();RemixPlan.arrange(q);RemixPlan.finish(q,"e0","",true);for(int i=0;i<q.getJSONArray("entries").length();i++)check(!q.getJSONArray("entries").getJSONObject(i).getString("id").equals("e0"),"manual skip prevents later return");
 q=queue();q.getJSONObject("tracks").getJSONObject("t0").put("rangeStart",15).put("rangeEnd",60);RemixPlan.arrange(q);check(!q.getJSONArray("entries").getJSONObject(0).optBoolean("remix"),"manual excerpt is never replaced by an automatic snippet");
 q=queue();q.getJSONArray("entries").getJSONObject(0).getJSONArray("remixCues").getJSONObject(0).put("entryVerified",false);RemixPlan.arrange(q);check(q.getJSONArray("entries").getJSONObject(0).getJSONObject("dj").getDouble("start")==70,"unverified interior boundary is excluded");
 // Metadata can reorder proposals, but a played excerpt must never return.
 q=queue();RemixPlan.arrange(q);JSONObject heard=q.getJSONArray("entries").getJSONObject(0);RemixPlan.finish(q,"e0","",false);check(heard.getJSONArray("remixUsed").length()==1,"completed excerpt signature is persisted");heard.put("remixCues",new JSONArray().put(cue(70,128).put("energy",1)).put(cue(40,128)).put(cue(100,128).put("energy",0)));q.put("entries",new JSONArray().put(heard)).put("currentId","e0");RemixPlan.arrange(q);check(heard.getJSONObject("dj").getDouble("start")==70,"metadata reordering cannot replay the first heard section");RemixPlan.finish(q,"e0","",false);heard.put("remixCues",new JSONArray().put(cue(70,128).put("energy",1)).put(cue(40,128)).put(cue(100,128).put("energy",0)));RemixPlan.arrange(q);check(heard.getJSONObject("dj").getDouble("start")==100,"successive returns skip every persisted signature");RemixPlan.finish(q,"e0","",false);check(q.getJSONArray("entries").length()==0,"persisted signatures retain the three-visit cap");
 // A prepared next deck keeps its exact section/rate across refreshed metadata.
 q=queue();RemixPlan.arrange(q);JSONObject pinned=q.getJSONArray("entries").getJSONObject(1),pinnedCue=pinned.getJSONObject("dj");pinned.put("remixCues",new JSONArray().put(cue(100,128)).put(cue(40,128)).put(cue(70,128)));RemixPlan.arrange(q,pinned.getString("id"));check(q.getJSONArray("entries").getJSONObject(1)==pinned&&pinned.getJSONObject("dj")==pinnedCue,"metadata refresh preserves the already planned successor");q.getJSONArray("entries").getJSONObject(2).getJSONArray("remixCues").getJSONObject(0).put("bpm",128);RemixPlan.arrange(q,pinned.getString("id"));check(q.getJSONArray("entries").getJSONObject(1)==pinned,"freshly analysed alternatives cannot replace an explicitly pinned next deck");
 // UI has already chosen snippets at rate 1; native still matches a compatible successor.
 q=queue();JSONObject left=q.getJSONArray("entries").getJSONObject(0),right=q.getJSONArray("entries").getJSONObject(2);left.put("remix",true).put("dj",cue(40,128).put("rate",1));right.put("remix",true).put("dj",cue(40,126).put("rate",1)).put("remixCues",new JSONArray().put(cue(40,126)));q.put("entries",new JSONArray().put(left).put(right));RemixPlan.arrange(q);check(Math.abs(right.getJSONObject("dj").getDouble("rate")-128./126)<.000001,"UI-preselected snippets still match a reachable tempo before preloading");
 // Compact pools keep all 32 candidates and take precedence over stale verbose cues.
 q=queue();JSONObject pooled=q.getJSONArray("entries").getJSONObject(0);JSONArray compact=new JSONArray();for(int k=0;k<32;k++)compact.put(new JSONArray().put(k*5).put(k*5+12).put(128).put(.16).put(3.2).put(JSONObject.NULL).put(k==31?1:0).put(1).put(1));pooled.put("remixPool",compact);RemixPlan.arrange(q);check(pooled.getJSONObject("dj").getDouble("start")==155&&pooled.getJSONObject("dj").getBoolean("wordGuarded"),"compact pool candidate beyond the old 24 limit is decoded and selected by energy");check(!pooled.getJSONObject("dj").has("grid"),"null beat grid stays absent");
 // Different, heavily overlapping timestamps are still the same heard material.
 q=queue();pooled=q.getJSONArray("entries").getJSONObject(0);pooled.put("remixVisits",1).put("remixUsed",new JSONArray().put("40000:52000")).put("remixCues",new JSONArray().put(cue(40,128).put("energy",1)).put(cue(42,128).put("energy",1)).put(cue(100,128).put("energy",0)));RemixPlan.arrange(q);check(pooled.getJSONObject("dj").getDouble("start")==100,"unused but overlapping excerpt loses to genuinely new material");
 // Candidate choice is stable on refresh, while different session identities vary equal choices.
 Set<Double> choices=new HashSet<>();for(int k=0;k<20;k++){q=queue();pooled=q.getJSONArray("entries").getJSONObject(0);pooled.put("id","session-"+k).put("remixCues",new JSONArray().put(cue(40,128)).put(cue(70,128)).put(cue(100,128)));q.put("currentId","session-"+k);JSONObject clone=new JSONObject(q.toString());RemixPlan.arrange(q);RemixPlan.arrange(clone);double chosen=pooled.getJSONObject("dj").getDouble("start");check(chosen==clone.getJSONArray("entries").getJSONObject(0).getJSONObject("dj").getDouble("start"),"same session and visit always choose the same candidate");choices.add(chosen);}check(choices.size()>1,"equally good choices vary between sessions");
 // An unprepared next entry is rescored; an actual incoming pin stays untouched.
 q=queue();left=q.getJSONArray("entries").getJSONObject(0);right=q.getJSONArray("entries").getJSONObject(1);left.put("remix",true).put("dj",cue(40,128));right.put("remix",true).put("dj",cue(40,128).put("energy",0)).put("remixCues",new JSONArray().put(cue(40,128).put("energy",0)).put(cue(100,128).put("energy",1)));q.put("entries",new JSONArray().put(left).put(right));RemixPlan.arrange(q);check(right.getJSONObject("dj").getDouble("start")==100,"preselected but unprepared successor can choose a better candidate");JSONObject prepared=right.getJSONObject("dj");right.put("remixCues",new JSONArray().put(cue(70,128).put("energy",1)));RemixPlan.arrange(q,right.getString("id"));check(right.getJSONObject("dj")==prepared,"actual pinned successor preserves exact chosen section and speed");
 System.out.println("PROBE_PASSED moving_pool lookahead visits skips manual evidence");
 }
}'''}
    compile_probe(tmp_path,fixtures,['RemixPlan.java','DjPlan.java','PlaybackRange.java'],'RemixProbe')


def test_word_guarded_fade_budgets_require_both_markers_and_keep_incoming_overlap(tmp_path):
    fixtures={'com/aidj/music/GuardedFadeProbe.java':r'''package com.aidj.music;
import org.json.*;
public class GuardedFadeProbe {
 static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 static JSONObject entry(boolean remix,double fade,boolean words,boolean entry){return new JSONObject().put("remix",remix).put("dj",new JSONObject().put("start",20).put("end",remix?32:130).put("bpm",128).put("fade",fade).put("wordGuarded",words).put("entryVerified",entry));}
 public static void main(String[] ignored){
 JSONObject track=new JSONObject().put("duration",240);
 check(DjPlan.cue(track,entry(false,.25,true,true),true)!=null,"normal guarded minimum accepted");
 check(DjPlan.cue(track,entry(false,.249,true,true),true)==null,"normal budget cannot go below .25s");
 check(DjPlan.cue(track,entry(true,.15,true,true),true)!=null,"remix guarded minimum accepted");
 check(DjPlan.cue(track,entry(true,.149,true,true),true)==null,"remix budget cannot go below .15s");
 for(boolean remix:new boolean[]{false,true})for(boolean[] markers:new boolean[][]{{false,false},{false,true},{true,false}}){
 check(DjPlan.cue(track,entry(remix,.49,markers[0],markers[1]),true)==null,"legacy or partially marked cues retain the .5s minimum");
 }
 check(DjPlan.cue(track,entry(false,.5,false,false),true)!=null,"legacy normal cues still work");
 check(DjPlan.cue(track,entry(true,.5,false,true),true)!=null,"verified legacy remix cues still work");
 for(boolean remix:new boolean[]{false,true}){
 JSONObject e=entry(remix,remix?.16:.25,true,true);long window=DjPlan.overlap(track,e,true,1);check(window>=1500,"short outgoing budget does not shorten incoming blend");
 e.getJSONObject("dj").put("mix",.1).put("grid",.3);check(DjPlan.cue(track,e,true)==null,"explicit tiny incoming blend is rejected");e.getJSONObject("dj").put("mix",9);check(DjPlan.cue(track,e,true)==null,"explicit oversized incoming blend is rejected");e.getJSONObject("dj").put("mix",1.5);
 JSONObject next=entry(remix,remix?.16:.25,true,true);next.getJSONObject("dj").put("grid",.17);check(DjPlan.matchedOverlap(track,e,track,next,1,1)>=1500,"beat phase correction also preserves minimum incoming overlap");
 e.getJSONObject("dj").put("mix",3.2);window=DjPlan.overlap(track,e,true,1);double fraction=DjPlan.safeFade(track,e)/(double)window;
 for(int i=0;i<=1000;i++){double p=i/1000.0;float out=DjPlan.gain(p,false,fraction),in=DjPlan.gain(p,true,fraction);check(out>=0&&in>=0&&out+in<=.991,"short guarded fades keep gain headroom");if(p<1-fraction)check(Math.abs(out-.7)<.001,"outgoing phrase is held at full gain until its own short budget");}
 }
 JSONObject q=new JSONObject().put("djEnabled",true).put("djRemix",true).put("currentId","e").put("tracks",new JSONObject().put("t",track));JSONObject e=new JSONObject().put("id","e").put("trackId","t").put("remixCues",new JSONArray().put(entry(true,.14,true,true).getJSONObject("dj")).put(entry(true,.16,true,true).getJSONObject("dj")));q.put("entries",new JSONArray().put(e));RemixPlan.arrange(q);check(e.optBoolean("remix")&&Math.abs(e.getJSONObject("dj").getDouble("fade")-.16)<.000001,"remix planner filters guarded candidates with its own lower bound");
 System.out.println("PROBE_PASSED guarded_thresholds legacy_markers incoming_mix outgoing_words headroom remix_selection");
 }
}'''}
